#!/usr/bin/env bash
# Builds the gpueue .deb or .rpm from built binaries with nfpm
# (packaging/nfpm.yaml).
#
# The binaries must be for this machine's architecture: the shell completions
# are generated by running `BIN_DIR/gpueue completions <shell>`. The package
# version is the workspace version (a pre-release 0.2.0-rc.1 becomes
# 0.2.0~rc.1 inside the package, so that it sorts before 0.2.0). The file is
# written as (no `~`, which GitHub release assets cannot contain)
#   deb: OUT_DIR/gpueue_<workspace version>_<amd64|arm64>.deb
#   rpm: OUT_DIR/gpueue-<workspace version>-1.<x86_64|aarch64>.rpm
# and its path is printed.
#
# Usage: scripts/dist/build-package.sh BIN_DIR OUT_DIR [FORMAT]
#   FORMAT: deb (default) or rpm
# Environment:
#   GPUEUE_PKG_VERSION     package version instead of the workspace version
#                         (for tests: an upgrade between two packages of the
#                         same binaries)
#   GPUEUE_RPM_SIGNING_KEY an ASCII-armored GPG secret key file that signs the
#                         .rpm (its passphrase in NFPM_RPM_PASSPHRASE); unset
#                         or empty leaves the .rpm unsigned
# Uses `nfpm` from PATH, or downloads a pinned one (scripts/dist/get-nfpm.sh).
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
bin_dir="${1:?usage: $0 BIN_DIR OUT_DIR [FORMAT]}"
out="${2:?usage: $0 BIN_DIR OUT_DIR [FORMAT]}"
format="${3:-deb}"
case "$format" in
deb | rpm) ;;
*) echo "unsupported package format: $format" >&2; exit 2 ;;
esac

# shellcheck source=scripts/dist/lib.sh
. "$root/scripts/dist/lib.sh"
dist_arch
arch="$DIST_DEB_ARCH"
rpm_arch="${DIST_TARGET%%-*}"
version="${GPUEUE_PKG_VERSION:-}"
[ -n "$version" ] || version="$(workspace_version "$root")"
signing_key="${GPUEUE_RPM_SIGNING_KEY:-}"
if [ -n "$signing_key" ]; then
    [ "$format" = rpm ] || { echo "GPUEUE_RPM_SIGNING_KEY only applies to the rpm format" >&2; exit 2; }
    [ -f "$signing_key" ] || { echo "no such file: $signing_key" >&2; exit 1; }
    signing_key="$(cd "$(dirname "$signing_key")" && pwd)/$(basename "$signing_key")"
fi

if command -v nfpm >/dev/null 2>&1; then
    nfpm="$(command -v nfpm)"
else
    nfpm="$("$root/scripts/dist/get-nfpm.sh" "$root/target/dist-tools")"
fi

stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
mkdir -p "$stage/bin" "$stage/completions" "$stage/docs"
install -m 0755 "$bin_dir/gpueue" "$bin_dir/gpueue-helper" "$stage/bin/"
cp -r "$root/packaging" "$stage/"
cp "$root/README.md" "$root/LICENSE" "$stage/"
cp "$root/docs/install.md" "$root/docs/usage.md" "$root/docs/architecture.md" "$stage/docs/"
"$stage/bin/gpueue" completions bash >"$stage/completions/gpueue.bash"
"$stage/bin/gpueue" completions zsh >"$stage/completions/_gpueue"
"$stage/bin/gpueue" completions fish >"$stage/completions/gpueue.fish"

mkdir -p "$out"
out="$(cd "$out" && pwd)"
case "$format" in
deb) file="$out/gpueue_${version}_$arch.deb" ;;
rpm) file="$out/gpueue-$version-1.$rpm_arch.rpm" ;;
esac
(cd "$stage" && GPUEUE_PKG_ARCH="$arch" GPUEUE_PKG_VERSION="$version" GPUEUE_RPM_SIGNING_KEY="$signing_key" \
    "$nfpm" package --config packaging/nfpm.yaml --packager "$format" --target "$file" >&2)
echo "$file"
